package com.example.employeeactivity; import android.os.Bundle; import android.widget.TextView; import androidx.appcompat.app.AppCompatActivity; public class SecondaryActivity extends AppCompatActivity { @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_secondary);((TextView)findViewById(R.id.tvName)).setText("Employee Name : "+getIntent().getStringExtra("name"));((TextView)findViewById(R.id.tvId)).setText("Employee ID : "+getIntent().getStringExtra("id"));double basic=getIntent().getDoubleExtra("basic",0),hra=getIntent().getDoubleExtra("hra",0),da=getIntent().getDoubleExtra("da",0),gross=getIntent().getDoubleExtra("gross",0);((TextView)findViewById(R.id.tvBasic)).setText("Basic Salary : "+basic);((TextView)findViewById(R.id.tvHra)).setText("HRA (20%) : "+hra);((TextView)findViewById(R.id.tvDa)).setText("DA (10%) : "+da);((TextView)findViewById(R.id.tvGross)).setText("Gross Salary : "+gross);}}
